const files = $input.all().map((item) => item.json).filter((file) => {
  if (!file || !file.id) { return false; }
  const mime = String(file.mimeType || "");
  return mime !== "application/vnd.google-apps.folder";
});

if (files.length === 0) {
  throw new Error("No CV found in the Drive folder. Check cvFolderId in the Settings node.");
}

const rank = (file) => {
  const mime = String(file.mimeType || "");
  const name = String(file.name || "").toLowerCase();
  if (mime === "application/pdf" || name.endsWith(".pdf")) { return 0; }
  if (mime === "application/vnd.google-apps.document") { return 1; }
  if (mime === "application/vnd.openxmlformats-officedocument.wordprocessingml.document" || name.endsWith(".docx")) { return 2; }
  return 3;
};

files.sort((a, b) => rank(a) - rank(b));
const chosen = files[0];

return [{
  json: {
    id: chosen.id,
    name: chosen.name || "cv",
    mimeType: chosen.mimeType || "",
    configured: !String($("Settings").first().json.cvFolderId || "").startsWith("PASTE_")
  }
}];

const payload = $input.first().json;
const settings = $("Settings").first().json;
const file = $("Pick Cv File").first().json;

function extractText(value) {
  if (!value) { return ""; }
  if (typeof value === "string") { return value; }
  if (typeof value.text === "string" && value.text.length > 0) { return value.text; }
  if (typeof value.content === "string") { return value.content; }
  if (value.content && Array.isArray(value.content.parts)) {
    return value.content.parts.map((part) => (part && typeof part.text === "string") ? part.text : "").join("");
  }
  if (Array.isArray(value.parts)) {
    return value.parts.map((part) => (part && typeof part.text === "string") ? part.text : "").join("");
  }
  if (value.content && typeof value.content === "object") { return JSON.stringify(value.content); }
  return JSON.stringify(value);
}

const raw = extractText(payload);
const start = raw.indexOf("{");
const end = raw.lastIndexOf("}");

if (start === -1 || end === -1) {
  throw new Error("Gemini did not return JSON for the CV. First 200 characters: " + raw.slice(0, 200));
}

let parsed;
try {
  parsed = JSON.parse(raw.slice(start, end + 1));
} catch (error) {
  throw new Error("Gemini returned invalid JSON for the CV: " + error.message);
}

if (!parsed.personal_info || typeof parsed.personal_info !== "object") {
  throw new Error("The CV profile has no personal_info object. Check the CV file.");
}

const confidence = Number(parsed.extraction_confidence);
const now = new Date().toISOString();

return [{
  json: {
    id: "profile-" + settings.userId,
    user_id: settings.userId,
    version: 1,
    source_filename: file.name,
    extracted_at: now,
    personal_info_json: JSON.stringify(parsed.personal_info || {}),
    education_json: JSON.stringify(parsed.education || []),
    experience_json: JSON.stringify(parsed.experience || []),
    skills_json: JSON.stringify(parsed.skills || []),
    languages_json: JSON.stringify(parsed.languages || []),
    certifications_json: JSON.stringify(parsed.certifications || []),
    projects_json: JSON.stringify(parsed.projects || []),
    raw_text: "",
    extraction_confidence: isNaN(confidence) ? 0 : confidence,
    uncertain_elements_json: JSON.stringify(parsed.uncertain_elements || []),
    human_verified: false,
    created_at: now,
    updated_at: now
  }
}];

const settings = $("Settings").first().json;
const maxAgeDays = Number(settings.maxDaysOld) > 0 ? Number(settings.maxDaysOld) : 7;
const maxDescription = 20000;

function asText(value) {
  if (typeof value === "string") { return value.trim(); }
  if (Array.isArray(value)) {
    for (const entry of value) {
      const found = asText(entry);
      if (found) { return found; }
    }
  }
  return "";
}

function clean(value) {
  return asText(value)
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<br\s*\/?>/gi, " ")
    .replace(/<\/(p|div|li|h[1-6])>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#0?39;|&apos;|&rsquo;|&lsquo;/gi, "'")
    .replace(/&mdash;/gi, "-")
    .replace(/&ndash;/gi, "-")
    .replace(/\s+/g, " ")
    .trim();
}

const rows = $input.all().map((item) => item.json).filter((row) => row && typeof row === "object");
const jobs = rows.flatMap((row) => {
  if (Array.isArray(row)) { return row; }
  if (Array.isArray(row.jobs)) { return row.jobs; }
  return [row];
});

const offers = jobs.map((job) => ({
  external_id: job.id === undefined || job.id === null ? "" : String(job.id).trim(),
  external_source: "fantastic.jobs",
  title: clean(job.title),
  company_name: clean(asText(job.organization) || asText(job.org_linkedin_name)),
  company_domain: asText(job.domain_derived) || asText(job.org_linkedin_website) || asText(job.source_domain),
  description: clean(asText(job.description_text) || asText(job.description_html)).slice(0, maxDescription),
  url: asText(job.url),
  location: asText(job.locations_derived) || asText(job.locations_alt),
  contact_email: asText(job.ai_hiring_manager_email_address),
  posted_at: asText(job.date_posted) || asText(job.date_created)
})).filter((offer) => offer.external_id.length > 0);

const now = Date.now();
const fresh = offers.filter((offer) => {
  if (maxAgeDays <= 0) { return true; }
  const posted = Date.parse(offer.posted_at);
  if (Number.isNaN(posted)) { return true; }
  return (now - posted) <= maxAgeDays * 86400000;
});

if (fresh.length === 0) { return []; }

return fresh.map((offer) => ({ json: offer }));

const settings = $("Settings").first().json;
const profile = $("Parse Cv Profile").first().json;
const known = $("Read Known Offers").all().map((item) => item.json);
const knownIds = new Set(known.filter((row) => row && row.external_id).map((row) => String(row.external_id)));
const candidates = $input.all().map((item) => item.json);

function hash8(value) {
  let hash = 5381;
  for (let i = 0; i < value.length; i++) {
    hash = ((hash * 33) ^ value.charCodeAt(i)) >>> 0;
  }
  return hash.toString(16).padStart(8, "0");
}

function parseJson(value, fallback) {
  if (value && typeof value === "object") { return value; }
  try {
    const parsed = JSON.parse(String(value || ""));
    return parsed === null || parsed === undefined ? fallback : parsed;
  } catch (error) {
    return fallback;
  }
}

const fresh = candidates.filter((offer) => {
  if (!offer.external_id) { return false; }
  return !knownIds.has(String(offer.external_id));
});

const limit = Number(settings.maxOffers) > 0 ? Number(settings.maxOffers) : 3;
const now = new Date().toISOString();

return fresh.slice(0, limit).map((offer) => {
  const ref = "APP-" + hash8(String(offer.external_id));
  return {
    json: {
      // Offer row, flat: these keys match the Offers headers exactly.
      id: "offer-" + hash8(String(offer.external_id)),
      user_id: settings.userId,
      external_id: String(offer.external_id),
      external_source: String(offer.external_source),
      title: offer.title,
      company_name: offer.company_name,
      company_domain: offer.company_domain,
      description: offer.description,
      location: offer.location,
      contact_email: String(offer.contact_email || ""),
      status: "new",
      availability_status: "open",
      created_at: now,
      updated_at: now,
      // Draft context, ignored by the sheet write and used by the model prompt.
      trackingRef: ref,
      applicationId: "app-" + ref.slice(4),
      offerJson: JSON.stringify({
        id: String(offer.external_id),
        title: offer.title,
        company: offer.company_name,
        location: offer.location,
        url: offer.url,
        description: String(offer.description || "").slice(0, 4000)
      }),
      profileId: profile.id,
      profileJson: JSON.stringify({
        personal_info: parseJson(profile.personal_info_json, {}),
        education: parseJson(profile.education_json, []),
        experience: parseJson(profile.experience_json, []),
        skills: parseJson(profile.skills_json, []),
        languages: parseJson(profile.languages_json, []),
        certifications: parseJson(profile.certifications_json, []),
        projects: parseJson(profile.projects_json, [])
      })
    }
  };
});

const responses = $input.all();
const contexts = $("Build Draft Prompt").all();
const settings = $("Settings").first().json;

function extractText(value) {
  if (!value) { return ""; }
  if (typeof value === "string") { return value; }
  if (typeof value.text === "string" && value.text.length > 0) { return value.text; }
  if (typeof value.content === "string") { return value.content; }
  if (value.content && Array.isArray(value.content.parts)) {
    return value.content.parts.map((part) => (part && typeof part.text === "string") ? part.text : "").join("");
  }
  if (Array.isArray(value.parts)) {
    return value.parts.map((part) => (part && typeof part.text === "string") ? part.text : "").join("");
  }
  if (value.content && typeof value.content === "object") { return JSON.stringify(value.content); }
  return JSON.stringify(value);
}

if (responses.length !== contexts.length) {
  throw new Error("Draft count mismatch: " + responses.length + " model responses for " + contexts.length + " offers. Refusing to write a partial batch.");
}

return responses.map((response, index) => {
  const context = contexts[index].json;
  const raw = extractText(response.json);
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");

  if (start === -1 || end === -1) {
    throw new Error("Gemini did not return JSON for " + context.trackingRef + ". First 200 characters: " + raw.slice(0, 200));
  }

  let result;
  try {
    result = JSON.parse(raw.slice(start, end + 1));
  } catch (error) {
    throw new Error("Gemini returned invalid JSON for " + context.trackingRef + ": " + error.message);
  }

  if (result.application_ref && String(result.application_ref) !== context.trackingRef) {
    throw new Error("The model changed the tracking reference of " + context.trackingRef + ". Refusing to write a mismatched application.");
  }

  const allowed = ["apply", "consider", "skip"];
  const recommendation = allowed.indexOf(result.recommendation) === -1 ? "consider" : result.recommendation;
  let score = Math.round(Number(result.score));
  if (isNaN(score)) { score = 0; }
  if (score < 0) { score = 0; }
  if (score > 100) { score = 100; }

  const body = String(result.email_body || "").trim();
  const subjectBase = String(result.email_subject || "").trim() || ("Candidature " + context.offerTitle);
  const contact = String(context.contactEmail || "").trim();
  const trackingRef = context.trackingRef;
  const now = new Date().toISOString();
  const warnings = Array.isArray(result.warnings) ? result.warnings.slice() : [];

  if (body.length === 0 && recommendation !== "skip") {
    warnings.push("Truthfulness check: no e-mail body was produced for a non-skip recommendation.");
  }

  return {
    json: {
      id: context.applicationId,
      user_id: settings.userId,
      offer_id: context.offerId,
      profile_id: context.profileId,
      tracking_ref: trackingRef,
      status: "draft_ready",
      score: score,
      recommendation: recommendation,
      company_name: context.companyName,
      offer_title: context.offerTitle,
      contact_email: contact,
      email_subject: subjectBase,
      email_body: body,
      draft_to: contact ? contact : "A COMPLETER",
      draft_subject: (subjectBase + " - " + trackingRef).slice(0, 180),
      draft_body: body,
      draft_status: "ready_manual_send",
      sent_at: "",
      location: context.location,
      warnings_json: JSON.stringify(warnings),
      instructions: contact
        ? "Recipient found in the offer. Read the body, then send it yourself. This workflow never sends."
        : "No recipient was found for this offer. Fill draft_to, read the body, then send it yourself. This workflow never sends.",
      created_at: now,
      updated_at: now
    }
  };
});
